import { gzipSync } from 'node:zlib'

// The bundle report (core and 2D refactor plan, task 5.1): where a game's shipped bytes come from, by package. It
// reads each chunk's source map, which says for every stretch of generated code which source file it came from, so
// the report needs no new dependency and no plugin. The raw numbers are counts of generated bytes. A chunk's gzip size
// is shared out by the same proportions, because gzip compresses a chunk as a whole: an estimate, good for comparing
// one build with another (Effect's share before and after it leaves the browser), not an exact per-package size.

export interface SourceMap {
  readonly sources: readonly string[]
  readonly mappings: string
}

export interface Chunk {
  readonly code: string
  readonly map: SourceMap
}

export interface PackageShare {
  readonly name: string
  readonly rawBytes: number
  readonly gzipBytes: number
}

export interface Report {
  readonly totalRaw: number
  readonly totalGzip: number
  /** Largest gzip share first. */
  readonly packages: readonly PackageShare[]
}

const GAME = '(the game)'

/** The package a source file belongs to, from its path in the source map. */
export function packageOf(source: string): string {
  if (source.startsWith('\0')) return '(build helpers)'
  const installed = /node_modules\/(?:\.pnpm\/[^/]+\/node_modules\/)?((?:@[^/]+\/)?[^/]+)\//.exec(
    source.split('node_modules/.pnpm/').length > 1
      ? source.replace(/^.*node_modules\/\.pnpm\//, 'node_modules/.pnpm/')
      : source,
  )
  if (installed?.[1] && !installed[1].startsWith('.')) return installed[1]
  const workspace = /packages\/([^/]+)\/src\//.exec(source)
  if (workspace?.[1])
    return workspace[1] === 'automata' ? '@mcthaydt/automata' : `@mcthaydt/automata-${workspace[1]}`
  return GAME
}

const BASE64 = new Map(
  [...'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'].map((char, index) => [char, index]),
)

/** Decode one segment of a `mappings` string into its numbers (base-64 variable-length quantities). */
function decodeSegment(segment: string): number[] {
  const values: number[] = []
  let value = 0
  let shift = 0
  for (const char of segment) {
    const digit = BASE64.get(char) ?? 0
    value += (digit & 31) << shift
    if (digit & 32) {
      shift += 5
    } else {
      values.push(value & 1 ? -(value >> 1) : value >> 1)
      value = 0
      shift = 0
    }
  }
  return values
}

/** Generated bytes per source index for one chunk, and the bytes no segment covers. */
function bytesBySource(chunk: Chunk): { bySource: Map<number, number>; unmapped: number; mapped: number } {
  const bySource = new Map<number, number>()
  let mapped = 0
  let unmapped = 0
  let sourceIndex = 0
  const codeLines = chunk.code.split('\n')
  chunk.map.mappings.split(';').forEach((line, lineIndex) => {
    const length = codeLines[lineIndex]?.length ?? 0
    let column = 0
    const segments = line === '' ? [] : line.split(',').map(decodeSegment)
    segments.forEach((numbers, index) => {
      column += numbers[0] ?? 0
      if (numbers.length >= 4) sourceIndex += numbers[1] ?? 0
      const next = segments[index + 1] ? column + (segments[index + 1]?.[0] ?? 0) : length
      const size = Math.max(0, Math.min(next, length) - column)
      if (numbers.length >= 4) {
        bySource.set(sourceIndex, (bySource.get(sourceIndex) ?? 0) + size)
        mapped += size
      } else unmapped += size
    })
  })
  // Whatever the segments leave, newlines excepted, is generated glue with no source.
  const total = codeLines.reduce((sum, line) => sum + line.length, 0)
  return { bySource, unmapped: unmapped + (total - mapped - unmapped), mapped }
}

export interface ReportOptions {
  /** The gzip size of a chunk's code; the real compressor unless a test passes its own. */
  readonly gzip?: (code: string) => number
}

/** Add up the chunks of one build by package. */
export function reportChunks(chunks: readonly Chunk[], options: ReportOptions = {}): Report {
  const gzip = options.gzip ?? ((code: string) => gzipSync(code).length)
  const raw = new Map<string, number>()
  const zipped = new Map<string, number>()
  let totalRaw = 0
  let totalGzip = 0
  for (const chunk of chunks) {
    const { bySource, unmapped } = bytesBySource(chunk)
    const sizes = new Map<string, number>()
    for (const [index, bytes] of bySource) {
      const name = packageOf(chunk.map.sources[index] ?? '')
      sizes.set(name, (sizes.get(name) ?? 0) + bytes)
    }
    if (unmapped > 0) sizes.set('(unmapped)', (sizes.get('(unmapped)') ?? 0) + unmapped)
    const chunkRaw = [...sizes.values()].reduce((sum, bytes) => sum + bytes, 0)
    const chunkGzip = gzip(chunk.code)
    for (const [name, bytes] of sizes) {
      raw.set(name, (raw.get(name) ?? 0) + bytes)
      zipped.set(name, (zipped.get(name) ?? 0) + (chunkRaw === 0 ? 0 : (bytes / chunkRaw) * chunkGzip))
    }
    totalRaw += chunkRaw
    totalGzip += chunkGzip
  }
  const packages = [...raw]
    .map(([name, rawBytes]) => ({ name, rawBytes, gzipBytes: zipped.get(name) ?? 0 }))
    .sort((a, b) => b.gzipBytes - a.gzipBytes || a.name.localeCompare(b.name))
  return { totalRaw, totalGzip, packages }
}

const kilobytes = (bytes: number): string => (bytes / 1000).toFixed(2)
const percent = (part: number, whole: number): string =>
  `${(whole === 0 ? 0 : (part / whole) * 100).toFixed(1)}%`

/** The report as a Markdown table, for the progress page. */
export function formatTable(report: Report): string {
  return [
    '| Package | Raw (kB) | Gzip (kB) | Share of gzip |',
    '|---|---|---|---|',
    ...report.packages.map(
      (row) =>
        `| ${row.name} | ${kilobytes(row.rawBytes)} | ${kilobytes(row.gzipBytes)} | ${percent(row.gzipBytes, report.totalGzip)} |`,
    ),
    `| **Total** | ${kilobytes(report.totalRaw)} | ${kilobytes(report.totalGzip)} | 100.0% |`,
  ].join('\n')
}
